dtsPropsFor.EmptySide:
/** The wording set: always chromeFor("ja") or chromeFor("en"), exported by this library. */
wording: Chrome;
/** The week's figures; allowance null hides spend (no approval read). */
figures: { asked: number; finished: number; answered: number; decidedWithoutAsking: number; allowance: ({ spentUsd: number; heldUsd: number; heldTries: number; heldInProgress: boolean; approvedUsd: number } & { leftUsd: number }) | null };
/** Requests under way, each with its five steps. */
running: readonly { messageId: string; title: string; repository: string | null; goingSaid: string; allowance: { spentUsd: number; heldUsd: number; heldTries: number; heldInProgress: boolean; approvedUsd: number } | null; tries: { at: number; of: number } | null; steps: readonly { name: "scope" | "work" | "checks" | "reading" | "approval" | "publish" | "landing"; state: "done" | "waiting" | "ahead" | "yours" }[] }[];
hrefOf: (messageId: string) => string;

dtsPropsFor.EventLines:
events: readonly { id: string; kind: "person" | "passed" | "failed" | "decided" | "other"; said: string; at: string; atMs: number; tryAt?: number | null; yours?: boolean; href?: string; linkSaid?: string }[];
/** Id of the event the last-looked line sits above, or null for no line. */
lastLookedAbove: string | null;
lastLookedSaid: string;

dtsPropsFor.FoldedLine:
/** A shut run of event lines (a native <details>). Items are { kind: "event"; event } or a nested fold. */
fold: { kind: "fold"; id: string; said: string; at: string; lines: number; inside: readonly ({ kind: "event"; event: { id: string; kind: "person" | "passed" | "failed" | "decided" | "other"; said: string; at: string; atMs: number; tryAt?: number | null; yours?: boolean; href?: string; linkSaid?: string } } | { kind: "fold"; [k: string]: unknown })[] };
/** The word the fold offers, e.g. "開く". */
open: string;

dtsPropsFor.GovernanceLine:
/** The wording set: always chromeFor("ja") or chromeFor("en"), exported by this library. */
wording: Chrome;
/** What was agreed for the request: allowance, tries, reach, the remaining chain. */
governance: {
  repository: string | null;
  askedAtMs: number;
  allowance: { spentUsd: number; heldUsd: number; heldTries: number; heldInProgress: boolean; approvedUsd: number } | null;
  byTry: readonly { costUsd: number | null; running: boolean }[];
  atBudgetCap: { costUsd: number; capUsd: number } | null;
  tries: { at: number; of: number } | null;
  chain: readonly { step: "answer" | "proposal" | "merge"; state: "done" | "waiting" | "ahead" | "yours" }[];
  worker: { provider: string; chosen: boolean } | null;
  touches: { places: readonly { repository: string; root: string }[]; acts: readonly string[] } | null;
  decided: { count: number; byRule: readonly unknown[] };
};
askedSaid: string;
others?: string;

dtsPropsFor.PartsSide:
/** The wording set: always chromeFor("ja") or chromeFor("en"), exported by this library. */
wording: Chrome;
/** One step per part of a request split into several lines; `yours` draws the one amber row. */
parts: readonly { name: string; said: string; yours: boolean; links: readonly { href: string; said: string; ask?: true }[] }[];

dtsPropsFor.ScopeSide:
/** The wording set: always chromeFor("ja") or chromeFor("en"), exported by this library. */
wording: Chrome;
steps: readonly { name: "scope" | "work" | "checks" | "reading" | "approval" | "publish" | "landing"; state: "done" | "waiting" | "ahead" | "yours" }[];

dtsPropsFor.SideSteps:
/** The wording set: always chromeFor("ja") or chromeFor("en"), exported by this library. */
wording: Chrome;
/** The steps to the end, in order: work, checks, reading, approval, landing (scope first on a scope screen). */
