  url: string | null; number: string | null; atMs: number; pushedOnto: boolean;
  checks: { kind: "running" } | { kind: "green"; counted: number | null; passed: number | null; skipped: number | null } | { kind: "red"; failed: readonly string[]; cancelled: readonly string[]; timedOut: readonly string[] } | { kind: "none" } | { kind: "conflict" } | { kind: "rerunning" };
  checksAtMs: number | null; checksCommit: string | null;
  merged: { into: string; method: string | null; outside: boolean; by: string | null; atMs: number } | null;
  closedAtMs: number | null;
  closedOut: { deleted: number; refused: number; worktreesGone: number; worktreesKept: number } | null;
  conflictsWith: string | null;
  withheld: { head: string; why: string; askId: string | null; gateLapId: string | null; atMs: number } | null;
  rerun: { head: string; ran: boolean; why: string | null; checkRunIds: readonly number[]; atMs: number } | null;
  moved: { from: string; to: string; commits: readonly { sha: string; subject: string }[]; more: number } | null;
};
conflictFix?: "offered" | "running" | "waits" | null;
mergesOnGreen?: boolean;

