list: { yourTurn: readonly { messageId: string; title: string; repository: string | null; state: "waitingOnYou" | "running" | "approved" | "finished" | "stopped" | "drafting" | "notStarted" | "question"; published?: unknown | null; flowStop?: boolean; press?: boolean; atMs: number }[]; days: readonly { cut: "today" | "yesterday" | "lastWeek" | "month" | "older"; rows: readonly { messageId: string; title: string; repository: string | null; state: "waitingOnYou" | "running" | "approved" | "finished" | "stopped" | "drafting" | "notStarted" | "question"; published?: unknown | null; flowStop?: boolean; press?: boolean; atMs: number }[] }[]; lastLookedAbove: string | null; paused?: readonly string[]; asking?: readonly { repository: string; request: string; points: number; askedAtMs: number }[] };
